  <title>Cat FAQ</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(17, 24, 39, 0.92);
      --panel-strong: rgba(30, 41, 59, 0.95);
      --border: rgba(148, 163, 184, 0.2);
      --text: #e5eefc;
      --muted: #b8c5db;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.5);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.16), transparent 32%),
        linear-gradient(180deg, #020617 0%, var(--bg) 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

    .app-shell {
      width: min(100%, 880px);
      background: linear-gradient(180deg, rgba(15, 23, 42, 0.9), rgba(15, 23, 42, 0.82));
      border: 1px solid var(--border);
      border-radius: 28px;
      padding: 32px;
      box-shadow: var(--shadow);
      backdrop-filter: blur(20px);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 0.78rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 12px;
    }

    .eyebrow::before {
      content: "";
      width: 28px;
      height: 1px;
      background: currentColor;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.3rem);
      line-height: 1.05;
    }

    .intro {
      margin: 14px 0 28px;
      max-width: 62ch;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .faq-list {
      display: grid;
      gap: 16px;
    }

    .example {
      border: 1px solid var(--border);
      background: linear-gradient(180deg, rgba(30, 41, 59, 0.68), rgba(15, 23, 42, 0.92));
      border-radius: 20px;
      overflow: hidden;
      transition: border-color 180ms ease, transform 180ms ease, background 180ms ease;
    }

    .example:hover,
    .example:focus-within {
      border-color: rgba(125, 211, 252, 0.45);
      transform: translateY(-1px);
    }

    .question-button {
      all: unset;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      width: 100%;
      padding: 22px 24px;
      cursor: pointer;
    }

    .question-text {
      font-size: 1.05rem;
      font-weight: 700;
      line-height: 1.45;
      color: var(--text);
    }

    .icon {
      flex: 0 0 auto;
      width: 36px;
      height: 36px;
      border-radius: 999px;
      display: grid;
      place-items: center;
      color: var(--accent);
      background: rgba(56, 189, 248, 0.1);
      border: 1px solid rgba(56, 189, 248, 0.18);
      transition: transform 180ms ease, background 180ms ease, color 180ms ease;
      font-size: 1.25rem;
      font-weight: 400;
    }

    .question-button[aria-expanded="true"] .icon {
      transform: rotate(45deg);
      background: rgba(56, 189, 248, 0.18);
      color: #d7f5ff;
    }

    .details {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 220ms ease;
    }

    .details.open {
      grid-template-rows: 1fr;
    }

    .details-inner {
      overflow: hidden;
    }

    .answer {
      margin: 0;
      padding: 0 24px 22px;
      color: var(--muted);
      line-height: 1.75;
    }

    .answer strong {
      color: #f8fbff;
    }

    @media (max-width: 640px) {
      .app-shell {
        padding: 24px 18px;
        border-radius: 22px;
      }

      .question-button,
      .answer {
        padding-left: 18px;
        padding-right: 18px;
      }
    }
  </style>
</head>
<body>
  <div id="root"></div>
  <script>
    const faqs = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel relaxed and content, but purring can also be a way to self-soothe during stress or recovery. It is one of the most familiar signals cats use to communicate comfort and calm."
      },
      {
        question: "How much sleep do cats usually need?",
        answer: "Most cats sleep between 12 and 16 hours a day. Kittens, senior cats, and very active cats may sleep even more because their bodies spend a lot of time restoring energy between bursts of activity."
      },
      {
        question: "Why do cats knead with their paws?",
        answer: "Kneading is a behavior that starts in kittenhood and often continues into adulthood. Cats may knead when they feel safe, when they are settling into a cozy spot, or when they are marking an area with scent glands in their paws."
      },
      {
        question: "Do indoor cats still need play and enrichment?",
        answer: "Yes. Indoor cats benefit from daily play, scratching surfaces, climbing spots, and window views. These activities support exercise, reduce boredom, and help satisfy natural hunting and exploring instincts."
      },
      {
        question: "What should I do if my cat suddenly changes behavior?",
        answer: "A sudden change in appetite, litter box habits, energy, or sociability can signal stress or illness. It is best to watch for patterns and contact a veterinarian if the change is strong, persistent, or paired with other symptoms."
      }
    ];

    function FAQItem({ question, answer, index }) {
      const buttonId = "faq-button-" + index;
      const panelId = "faq-panel-" + index;

      return `
        <div class="example">
          <button
            class="question-button"
            id="${buttonId}"
            type="button"
            aria-expanded="false"
            aria-controls="${panelId}"
          >
            <span class="question-text">${question}</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div
            class="details"
            id="${panelId}"
            role="region"
            aria-labelledby="${buttonId}"
            hidden
          >
            <div class="details-inner">
              <p class="answer">${answer}</p>
            </div>
          </div>
        </div>
      `;
    }

    function FAQList({ items }) {
      return `
        <div class="faq-list">
          ${items.map((item, index) => FAQItem({ ...item, index })).join("")}
        </div>
      `;
    }

    function App() {
      return `
        <main class="app-shell">
          <div class="eyebrow">Cat Care Guide</div>
          <h1>Frequently asked questions about cats</h1>
          <p class="intro">
            Explore quick answers about common feline habits, health signals, and everyday care.
            Each question starts collapsed, so you can open only the topics you want.
          </p>
          ${FAQList({ items: faqs })}
        </main>
      `;
    }

    document.getElementById("root").innerHTML = App();

    document.querySelectorAll(".question-button").forEach((button) => {
      button.addEventListener("click", () => {
        const panel = document.getElementById(button.getAttribute("aria-controls"));
        const expanded = button.getAttribute("aria-expanded") === "true";

        button.setAttribute("aria-expanded", String(!expanded));
        panel.hidden = expanded;
        panel.classList.toggle("open", !expanded);
      });
    });
  </script>
</body>
</html>
