       content: "";
       width: 28px;
       height: 1px;
       background: currentColor;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3.3rem);
       line-height: 1.05;
     }

     .intro {
       margin: 14px 0 28px;
       max-width: 62ch;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.7;
     }

     .faq-list {
       display: grid;
       gap: 16px;
     }

     .example {
       border: 1px solid var(--border);
       background: linear-gradient(180deg, rgba(30, 41, 59, 0.68), rgba(15, 23, 42, 0.92));
       border-radius: 20px;
       overflow: hidden;
       transition: border-color 180ms ease, transform 180ms ease, background 180ms ease;
     }

     .example:hover,
     .example:focus-within {
       border-color: rgba(125, 211, 252, 0.45);
       transform: translateY(-1px);
     }

     .question-button {
       all: unset;
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 20px;
       width: 100%;
       padding: 22px 24px;
       cursor: pointer;
