     .question-text {
       font-size: 1.05rem;
       font-weight: 700;
       line-height: 1.45;
       color: var(--text);
     }

     .icon {
       flex: 0 0 auto;
       width: 36px;
       height: 36px;
       border-radius: 999px;
       display: grid;
       place-items: center;
       color: var(--accent);
       background: rgba(56, 189, 248, 0.1);
       border: 1px solid rgba(56, 189, 248, 0.18);
       transition: transform 180ms ease, background 180ms ease, color 180ms ease;
       font-size: 1.25rem;
       font-weight: 400;
     }

     .question-button[aria-expanded="true"] .icon {
       transform: rotate(45deg);
       background: rgba(56, 189, 248, 0.18);
       color: #d7f5ff;
     }

     .details {
       display: grid;
       grid-template-rows: 0fr;
       transition: grid-template-rows 220ms ease;
     }

     .details.open {
       grid-template-rows: 1fr;
     }

     .details-inner {
       overflow: hidden;
     }

     .answer {
       margin: 0;
       padding: 0 24px 22px;
       color: var(--muted);
       line-height: 1.75;
     }

     .answer strong {
       color: #f8fbff;
     }

     @media (max-width: 640px) {
       .app-shell {
